import {createHash} from 'node:crypto';

// These definitions are generated by the fixed structured SQL tools. Output
// aliases, keyword case and whitespace cannot turn a query into independent
// evidence. This is a conservative identity check, not a SQL semantic prover.
export function queryEvidenceIdentity(data){
 const q=data?.queryDefinition;if(!data?.queryHash||!q||typeof q.sql!=='string'||!Array.isArray(q.params))return null;
 if(q.kind==='mongodb'){const spec=JSON.parse(q.sql),a=spec.arguments;const canonical=x=>{if(Array.isArray(x))return x.map(canonical);if(!x||typeof x!=='object')return x;const out=Object.fromEntries(Object.keys(x).sort().filter(k=>k!=='as').map(k=>[k,canonical(x[k])]));const scalar=v=>out.type==='date'?new Date(v).toISOString():out.type==='objectId'?v.toLowerCase():out.type==='int64'?String(BigInt(v)):out.type==='decimal'?(()=>{let s=String(v),negative=s.startsWith('-');s=s.replace(/^[-+]/,'');let [a,b='']=s.split('.');a=a.replace(/^0+(?=\d)/,'');b=b.replace(/0+$/,'');return (negative&&(a!=='0'||b)?'-':'')+a+(b?'.'+b:'');})():v;if(Object.hasOwn(out,'value'))out.value=out.op==='in'&&Array.isArray(out.value)?out.value.map(scalar).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b))):scalar(out.value);return out;};for(const key of ['collections','columns','groupColumns','filters','aggregates'])if(Array.isArray(a?.[key]))a[key]=a[key].map(canonical).sort((x,y)=>JSON.stringify(x).localeCompare(JSON.stringify(y)));return createHash('sha256').update(JSON.stringify(['mongodb',canonical(spec),q.params])).digest('hex');}
 const tokens=q.sql.match(/`(?:``|[^`])*`|'(?:''|\\.|[^'\\])*'|"(?:""|\\.|[^"\\])*"|[a-z_][a-z0-9_]*|[^\s]/gi)??[];
 const normalized=[];
 for(let i=0;i<tokens.length;i++){
  const token=tokens[i];
  if(/^as$/i.test(token)&&/^(?:`(?:``|[^`])*`|[a-z_][a-z0-9_]*)$/i.test(tokens[i+1]??'')){i++;continue;}
  normalized.push(/^[`'"]/.test(token)?token:token.toLowerCase());
 }
 const sql=normalized.join(' ');
 return createHash('sha256').update(JSON.stringify([sql,q.params.map(v=>String(v))])).digest('hex');
}
